// Package macro is the worked example behind tools/simd/PLAN.md: an AVX2
// kernel composed from assembler macros rather than generated by a program.
//
// It exists to be read beside the plan and to keep the plan honest. The kernel
// here is the one lib/bitbuffer runs, and it assembles to the same instructions
// and runs at the same speed as the avo-generated version, with no generator,
// no tool dependency and no build step.
//
// It is not imported by anything. lib/bitbuffer keeps the generated kernel
// until phase 1 of the plan is taken.
package macro

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// SHIFT_BLOCK is the number of bytes the kernel handles per iteration.
const (
	SHIFT_BLOCK   = 32
	BITS_PER_BYTE = 8
)

// Shift writes out[i] = data[i-1]<<free | data[i]>>used for the whole of data,
// handing the middle to the macro-composed kernel and doing the edges in Go.
//
// out must be one byte longer than data, and carry holds the bits of the
// partial byte the caller has already written.
//
// Revisions:
//   - 2026-09-22 09:12: initial creation
func Shift(out, data []byte, used uint8, carry uint64) {
	if len(data) == 0 {
		return
	}

	free := BITS_PER_BYTE - used
	out[0] = byte(carry<<free | uint64(data[0])>>used)

	// The kernel reads one byte beyond each block, so the block count comes off
	// len(data)-1 rather than len(data).
	// The kernel is AVX2, so it runs only where lib/cpu has established that
	// AVX2 is present and the operating system preserves the YMM state across
	// a context switch.
	blocks := (len(data) - 1) / SHIFT_BLOCK * SHIFT_BLOCK
	if !cpu.HAS_AVX2 {
		blocks = 0
	}

	if blocks > 0 {
		_ShiftBlocks(out[1:1+blocks], data, free, used)
	}

	for i := 1 + blocks; i < len(data); i++ {
		out[i] = byte(uint64(data[i-1])<<free | uint64(data[i])>>used)
	}

	out[len(data)] = byte(uint64(data[len(data)-1]) << free)
}
